head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.pBndApplId = '';
scwin.pBndListProcsTpCd = '';
scwin.pMktactCd = '';
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
scwin.arrPar = new Array();
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // 패널라운드 처리
        $c.bns.BnsPanelToGroupBox(pnl_Search);

        // 채권유형코드
        scwin.setComboCode();

        // 조회 시작일 -7일, 종료일 현재일자로 설정
        edt_StartDd.setValue($c.ut.cGetMinusDate2(scwin.vCurDate, 7));
        edt_EndDd.setValue(scwin.vCurDate);

        // 발행기관 검색 필드 포커스
        txb_IsurNm.focus();
        // 조회
        scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20100.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20100.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        scwin.showIsur(txb_IsurNm);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20100.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name txb_IsurNm_onkeypress
 * @description txb_IsurNm onkeypress 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_IsurNm_onkeypress = function() {
    try {
        if ($c.stf.compareFromToDate2(edt_StartDd, edt_EndDd)) {
            if (window.event.keyCode === 13) scwin.search();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20100.txb_IsurNm_onkeypress" });
    }
};

/**
 * @method
 * @name img_IsuNm_onclick
 * @description img_IsuNm 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_IsuNm_onclick = function() {
    try {
        scwin.showIsu(txb_IsuNm);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20100.img_IsuNm_onclick" });
    }
};

/**
 * @method
 * @name txb_IsuNm_onkeypress
 * @description txb_IsuNm onkeypress 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_IsuNm_onkeypress = function() {
    try {
        if ($c.stf.compareFromToDate2(edt_StartDd, edt_EndDd)) {
            if (window.event.keyCode === 13) scwin.search();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20100.txb_IsuNm_onkeypress" });
    }
};

/**
 * @method
 * @name img_StartDd_onclick
 * @description img_StartDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_StartDd_onclick = function() {
    try {
        popUpCalendar2(edt_StartDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20100.img_StartDd_onclick" });
    }
};

/**
 * @method
 * @name img_EndDd_onclick
 * @description img_EndDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_EndDd_onclick = function() {
    try {
        popUpCalendar2(edt_EndDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20100.img_EndDd_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    try {
        if ($c.stf.compareFromToDate2(edt_StartDd, edt_EndDd)) {
            scwin.search();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20100.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_ToExcel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ToExcel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDBNS20100.xml', SCREN_PROCS_TP_CD_07, '');
        const title = '연부과금 환급처리내역';
        const fileNm = scwin.vCurDate + '_' + title;
        $c.data.downloadGridViewExcel(grd_List, {fileName: title, type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20100.btn_ToExcel_onclick" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_OnDblClick = function(row, colid) {
    try {
        if (dts_List.getRowCount() === 0) return;
        if (row > 0) {
            scwin.pBndApplId = dts_List.getCellData(row, "BND_APPL_ID");
            scwin.pBndListProcsTpCd = dts_List.getCellData(row, "BND_LIST_PROCS_TP_CD");
            scwin.pMktactCd = dts_List.getCellData(row, "BND_MKTACT_TP_CD");
            scwin.fn_GetPar = scwin.anfeeRefnd;
            scwin.fn_SetPar = scwin.setAnfeeRefnd;
            $c.bns.fn_PopAnfeeRefnd(grd_List);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20100.grd_List_OnDblClick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description 리스트를 조회 한다.
 * @returns {void}
 * @hidden N
 */
scwin.search = function() {
    const dsNm = 'BNS_ANUL_FEE_REFND_LIST';
    const qryId = 'lds.stf.bnslistbzappl.select.selectAnulfeeRefndProcs';
    let param = '';
    param += '&{P}V_ISUR_CD=' + txb_IsurNm.getValue();
    param += '&{P}V_ISU_CD_NM=' + txb_IsuNm.getValue();
    param += '&{P}V_TERM_TYP=' + cmb_TermType.getValue();
    param += '&{P}V_START_DD=' + edt_StartDd.getValue();
    param += '&{P}V_END_DD=' + edt_EndDd.getValue();
    param += '&{P}V_BND_TP_CD=' + cmb_BndTpCd.getValue();
    $c.bns.fn_SearchBns('ULDBNS20100.xml', dts_List, dsNm, qryId, param);
};

/**
 * @method
 * @name setComboCode
 * @description 콤보데이터 정의 (채권유형코드)
 * @returns {void}
 * @hidden N
 */
scwin.setComboCode = function() {
    $c.bns.fn_SetBnsCombo('ULDBNS20100.xml', dts_BndTpCd, '01422');
    if (dts_BndTpCd.getCellData(1, "VALUE") === '') {
        dts_BndTpCd.setCellData(1, "TEXT", '전체');
        cmb_BndTpCd.setSelectedIndex(0);
    }
};

/**
 * @method
 * @name getParIsurCd
 * @description 발행기관 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsurCd = function(arrPar) {
    scwin.arrPar[0] = {
        ISUR_CD: txb_IsurNm.getValue()
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

/**
 * @method
 * @name setParIsurCd
 * @description 발행기관 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsurCd = function(arrPar) {
    txb_IsurNm.setValue(scwin.arrPar[0].ISUR_CD);
};

/**
 * @method
 * @name showIsur
 * @description 발행기관 팝업을 보여준다.
 * @param {String} txb_IsurNm txb_IsurNm
 * @returns {void}
 * @hidden N
 */
scwin.showIsur = function(txb_IsurNm) {
    scwin.fn_GetPar = scwin.getParIsurCd;
    scwin.fn_SetPar = scwin.setParIsurCd;
    $c.bns.fn_PopIsurSearch(txb_IsurNm);
};

/**
 * @method
 * @name getParIsuCd
 * @description 상장채권종목 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsuCd = function(arrPar) {
    scwin.arrPar[0] = {
        LIST_TYPE_CD: '2',
        ISU_NM: txb_IsuNm.getValue(),
        ISUR_NM: txb_IsurNm.getValue()
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

/**
 * @method
 * @name setParIsuCd
 * @description 상장채권종목 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsuCd = function(arrPar) {
    txb_IsuNm.setValue(scwin.arrPar[0].STD_CD);
};

/**
 * @method
 * @name showIsu
 * @description 상장채권종목 팝업을 보여준다.
 * @param {String} IsuNm IsuNm
 * @returns {void}
 * @hidden N
 */
scwin.showIsu = function(IsuNm) {
    scwin.fn_GetPar = scwin.getParIsuCd;
    scwin.fn_SetPar = scwin.setParIsuCd;
    $c.bns.fn_PopListBndIsuSearch(txb_IsuNm);
};

/**
 * @method
 * @name anfeeRefnd
 * @description 연부과금 환급수수료 등록 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.anfeeRefnd = function(arrPar) {
    scwin.arrPar[0] = {
        BND_APPL_ID: scwin.pBndApplId,
        BND_LIST_PROCS_TP_CD: scwin.pBndListProcsTpCd,
        MKTACT_TP_CD: scwin.pMktactCd,
        SCREN_ID: 'ULDBNS20100.xml'
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

/**
 * @method
 * @name setAnfeeRefnd
 * @description 연부과금 환급수수료 등록 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setAnfeeRefnd = function(arrPar) {
    if ("Y" === scwin.arrPar[0].REG_YN) {
        dts_List.Reset();
    }
};
